if(!msg.payload.username || !msg.payload.password) {
    msg.message = "Kullanıcı adı ve parola boş bırakılamaz."
    return [null, msg]
}

msg.formData = msg.payload

msg.payload = {
    username: msg.payload.username
}

return msg;

if(!msg.payload) {
    msg.message = "Kullanıcı adı veya parola hatalı."
    return [null, msg];
}

msg.user = msg.payload
msg.plainPass = msg.formData.password
msg.hashPass = msg.user.password

return msg;

if(!msg.match) {
    msg.message = "Kullanıcı adı veya parola hatalı."
    return [null, msg];
}

msg.payload = {
    username: msg.user.username
}

return msg;

msg.cookies = {
    token: msg.payload
}

msg.successMessage = msg.formData.username + " başarıyla giriş yaptı."
delete msg.formData

return msg;

msg.cookies = {
    token: null
}

msg.successMessage = "Başarıyla çıkış yapıldı."

return msg;

let userData = msg.payload
msg.payload = [
    {
        username: userData.username
    },
    {
        $set: userData
    },
    {
        upsert: true
    }
]

return msg;

const requireFields = ["kategoriAdi", "destekPersoneli"]
msg.formData = msg.payload
const requireFieldsDisplay = {
    "kategoriAdi": "Kategori Adı",
    "destekPersoneli": "Destek Personeli"
}

for(let field in msg.formData) {
    if(requireFields.includes(field) && msg.formData[field]) continue
    node.error(requireFieldsDisplay[field] + " alanı dolu olmak zorundadır.", msg);
    return
}

msg.payload = [
    {
        kategoriAdi: msg.formData.kategoriAdi
    }
]

return msg;

msg.payload = [
    {
        ...msg.formData,
        stamp: {
            user: msg.token.username,
            createdAt: new Date()
        }
    }
]
return msg;

// Başarı KOntrolü !!
if(msg.payload.acknowledged && msg.payload.insertedId) {
    msg.successMessage = msg.formData.kategoriAdi + " kategorisi başarıyla oluşturuldu."
    delete msg.formData
    return msg
}

msg.message = msg.formData.kategoriAdi + " kategorisi oluşturulamadı."
return [null, msg];
